CREATE OR REPLACE FUNCTION public.campaign_audience_match(_uid uuid,_targeting jsonb,_lang text,_is_ad boolean,_service boolean) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE aud jsonb:=coalesce(_targeting->'audiences','["all"]'::jsonb); langs jsonb:=_targeting->'languages'; t text:=public.account_type(_uid); pl text:=public.account_plan(_uid); bday date; adult boolean; BEGIN SELECT birthday INTO bday FROM profiles WHERE id=_uid; adult:=t<>'child' AND bday IS NOT NULL AND bday<=CURRENT_DATE-interval '18 years'; IF t='child' AND (_is_ad OR NOT _service) THEN RETURN false; END IF; IF _is_ad AND NOT coalesce(adult,false) THEN RETURN false; END IF; IF _lang IS NOT NULL AND langs IS NOT NULL AND jsonb_array_length(langs)>0 AND NOT(langs ? _lang) THEN RETURN false; END IF; RETURN aud ? 'all' OR (aud ? 'adults' AND adult) OR (aud ? 'parents' AND t='parent') OR (aud ? 'children' AND t='child') OR (aud ? 'free' AND pl='free') OR (aud ? 'pro' AND pl='pro') OR (aud ? 'pro_family' AND pl='pro_family'); END $$;
CREATE OR REPLACE FUNCTION public.claim_sponsored_challenge_reward(_challenge_id uuid,_day date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); c sponsored_challenges%ROWTYPE; v numeric; inserted int; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Not signed in' USING ERRCODE='42501'; END IF; IF _day IS NULL OR _day<CURRENT_DATE-1 OR _day>CURRENT_DATE+1 THEN RAISE EXCEPTION 'Invalid local day'; END IF; SELECT * INTO c FROM sponsored_challenges WHERE id=_challenge_id FOR UPDATE; IF NOT FOUND OR c.status NOT IN ('visible','active','completed') OR (c.removed_at IS NOT NULL AND c.removed_at<=now()) THEN RAISE EXCEPTION 'Challenge not available'; END IF; IF c.starts_at IS NULL OR now()<c.starts_at OR NOT public.campaign_audience_match(uid,c.eligibility,NULL,false,true) THEN RAISE EXCEPTION 'Challenge not eligible'; END IF; IF c.join_mode='manual' AND NOT EXISTS(SELECT 1 FROM sponsored_challenge_participants WHERE challenge_id=c.id AND user_id=uid) THEN RAISE EXCEPTION 'Join the challenge first'; END IF; IF EXISTS(SELECT 1 FROM sponsored_challenge_rewards WHERE challenge_id=c.id AND user_id=uid) THEN RETURN jsonb_build_object('granted',false,'reason','already_claimed'); END IF; v:=public.sponsored_progress_value(uid,c); IF v<c.target THEN RETURN jsonb_build_object('granted',false,'reason','not_completed','progress',v,'target',c.target); END IF; IF c.max_claims IS NOT NULL AND (SELECT count(*) FROM sponsored_challenge_rewards WHERE challenge_id=c.id)>=c.max_claims THEN RETURN jsonb_build_object('granted',false,'reason','sold_out'); END IF; INSERT INTO sponsored_challenge_participants(challenge_id,user_id,completed_at) VALUES(c.id,uid,now()) ON CONFLICT(challenge_id,user_id) DO UPDATE SET completed_at=coalesce(sponsored_challenge_participants.completed_at,now()); INSERT INTO sponsored_challenge_rewards(challenge_id,user_id,minutes,badge_id) VALUES(c.id,uid,c.reward_minutes,c.reward_badge_id) ON CONFLICT DO NOTHING; GET DIAGNOSTICS inserted=ROW_COUNT; IF inserted=0 THEN RETURN jsonb_build_object('granted',false,'reason','already_claimed'); END IF; IF c.reward_minutes>0 THEN INSERT INTO earned_balances(user_id,day,bonus_min) VALUES(uid,_day,c.reward_minutes) ON CONFLICT(user_id,day) DO UPDATE SET bonus_min=earned_balances.bonus_min+EXCLUDED.bonus_min; END IF; IF c.reward_badge_id IS NOT NULL THEN INSERT INTO user_badges(user_id,badge_id) VALUES(uid,c.reward_badge_id) ON CONFLICT(user_id,badge_id) DO NOTHING; END IF; RETURN jsonb_build_object('granted',true,'minutes',c.reward_minutes); END $$;
REVOKE ALL ON FUNCTION public.claim_sponsored_challenge_reward(uuid,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.claim_sponsored_challenge_reward(uuid,date) TO authenticated;
CREATE OR REPLACE FUNCTION public.claim_sponsored_challenge_reward(_challenge_id uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.claim_sponsored_challenge_reward(_challenge_id,CURRENT_DATE) $$;
ALTER TABLE public.user_daily_stats ADD COLUMN IF NOT EXISTS distance_km numeric NOT NULL DEFAULT 0; ALTER TABLE public.user_daily_stats ADD COLUMN IF NOT EXISTS exercise_minutes integer NOT NULL DEFAULT 0;
CREATE OR REPLACE FUNCTION public.sync_daily_movement_metrics() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.user_daily_stats SET distance_km=(SELECT coalesce(sum(distance_km),0) FROM public.activity_steps WHERE user_id=NEW.user_id AND day=NEW.day),exercise_minutes=(SELECT coalesce(sum(exercise_minutes),0) FROM public.activity_steps WHERE user_id=NEW.user_id AND day=NEW.day) WHERE user_id=NEW.user_id AND stat_date=NEW.day; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.sync_daily_movement_metrics() FROM PUBLIC,anon,authenticated; CREATE TRIGGER z_daily_movement_metrics AFTER INSERT OR UPDATE ON public.activity_steps FOR EACH ROW EXECUTE FUNCTION public.sync_daily_movement_metrics(); UPDATE public.user_daily_stats s SET distance_km=a.km,exercise_minutes=a.ex FROM (SELECT user_id,day,sum(distance_km) km,sum(exercise_minutes) ex FROM public.activity_steps GROUP BY user_id,day) a WHERE s.user_id=a.user_id AND s.stat_date=a.day;
CREATE TABLE public.admin_user_deletions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,target_user_id uuid NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','failed')),created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz); GRANT SELECT ON public.admin_user_deletions TO authenticated; GRANT ALL ON public.admin_user_deletions TO service_role; ALTER TABLE public.admin_user_deletions ENABLE ROW LEVEL SECURITY; CREATE POLICY deletion_request_owner ON public.admin_user_deletions FOR SELECT TO authenticated USING(actor_id=auth.uid() AND public.admin_can('users_delete'));
CREATE OR REPLACE FUNCTION public.admin_delete_user(_uid uuid,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF _uid IS NULL OR _uid=auth.uid() OR length(trim(coalesce(_reason,'')))<3 OR length(_reason)>1000 THEN RAISE EXCEPTION 'Invalid deletion request'; END IF; IF EXISTS(SELECT 1 FROM admin_roles WHERE user_id=_uid) THEN RAISE EXCEPTION 'Remove admin roles before deleting'; END IF; IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=_uid) THEN RAISE EXCEPTION 'User not found'; END IF; PERFORM public.admin_require_write('users_delete','user_delete_requested',_uid,jsonb_build_object('reason',_reason)); INSERT INTO public.admin_user_deletions(actor_id,target_user_id,reason) VALUES(auth.uid(),_uid,trim(_reason)) RETURNING id INTO rid; RETURN rid; END $$; REVOKE ALL ON FUNCTION public.admin_delete_user(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_delete_user(uuid,text) TO authenticated; COMMENT ON FUNCTION public.admin_delete_user(uuid,text) IS 'Queues audited MFA-authorized deletion. Complete via POST /api/public/admin-delete-user using the supported Auth admin API.';